<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
require dirname(__DIR__).'/app/music-library-preparation.php';
$user=current_user();if(!$user)redirect('/login.php');
$method=$_SERVER['REQUEST_METHOD']??'GET';if(!in_array($method,['GET','POST'],true)){http_response_code(405);header('Allow: GET, POST');exit;}
$canUpload=music_library_can_upload($user);$error='';$results=[];$tracks=[];
if($method==='POST'){
    if(!$canUpload){http_response_code(403);exit('Rollen gir ikke tilgang til opplasting.');}
    if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['csrf'],$_POST['csrf'])){http_response_code(403);exit('Opplastingen kunne ikke kontrolleres. Last siden på nytt og kontroller filstørrelsen.');}
    try{$action=$_POST['action']??'upload';if($action==='prepare'){
      foreach(['id','version','revision']as$k)if(!is_string($_POST[$k]??null))throw new InvalidArgumentException('Ugyldig klargjøring.');if(!preg_match('/^[0-9]{1,8}$/D',$_POST['revision']))throw new InvalidArgumentException('Ugyldig versjon.');
      $t=music_library_prepare($_POST['id'],$_POST['version'],(int)$_POST['revision'],$user,$_POST['csrf'],$_SESSION['csrf']);$_SESSION['music_library_results']=[['name'=>$t['originalName'],'message'=>'Filopplysninger og varighet er lest. Nettidentifisering og tagging er neste trinn.']];redirect('/music-library.php?track='.$t['id']);
    }if($action!=='upload')throw new InvalidArgumentException('Ukjent handling.');$files=$_FILES['tracks']??null;if(!is_array($files)||!is_array($files['name']??null)||count($files['name'])<1||count($files['name'])>10)throw new InvalidArgumentException('Velg mellom én og ti MP3-filer.');
      $total=0;foreach(['tmp_name','size','error']as$k)if(!is_array($files[$k]??null)||array_keys($files[$k])!==array_keys($files['name']))throw new InvalidArgumentException('Ugyldig opplasting.');
      foreach($files['size']as$n){if(!is_int($n)||$n<0)throw new InvalidArgumentException('Ugyldig filstørrelse.');$total+=$n;}if($total>64*1024*1024)throw new InvalidArgumentException('Velg færre filer: maksimalt 64 MiB per opplasting.');
      foreach($files['name']as$i=>$name){try{$r=music_library_upload(['name'=>$name,'tmp_name'=>$files['tmp_name'][$i],'size'=>$files['size'][$i],'error'=>$files['error'][$i]],$user,$_POST['csrf'],$_SESSION['csrf']);$results[]=['name'=>$name,'message'=>$r['duplicate']?'Finnes allerede – ingen ny kopi.':'Original lagret – venter på klargjøring.'];}catch(InvalidArgumentException $e){$results[]=['name'=>is_string($name)?$name:'Fil','message'=>$e->getMessage()];}catch(Throwable $e){error_log('Studio music upload failed');$results[]=['name'=>is_string($name)?$name:'Fil','message'=>'Kunne ikke lagre filen. Kontroller biblioteket før du prøver igjen.'];}}
      $_SESSION['music_library_results']=$results;redirect('/music-library.php');
    }catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable){error_log('Studio music preparation failed');$error='Klargjøringen kunne ikke fullføres. Original og eksisterende opplysninger er bevart.';}
}else{$results=$_SESSION['music_library_results']??[];unset($_SESSION['music_library_results']);}
$available=class_exists('finfo');if(!$available)$error='Filtypekontroll mangler på serveren. Opplasting er sperret.';try{$tracks=music_library_read();}catch(Throwable $e){$available=false;$error='Biblioteket kunne ikke leses. Opplasting er sperret til det er avklart.';}
$selected=null;$requested=$_GET['track']??null;if($requested!==null&&(!is_string($requested)||!preg_match('/^[a-f0-9]{32}$/D',$requested)))$error='Ugyldig låtreferanse.';else{foreach($tracks as$t)if($requested===null||$t['id']===$requested){$selected=$t;break;}if($requested!==null&&!$selected)$error='Låten finnes ikke i biblioteket.';}
$selectedMetadata=$selected?music_library_metadata($selected):null;$canListen=studio_can($user,'produce');
$extraStylesheet='/assets/music-library.css?v=20261013-2';require dirname(__DIR__).'/app/views/head.php';
?>
<div class="shell"><?php $activePage='music-library';require dirname(__DIR__).'/app/views/sidebar.php';?><div class="workspace"><header class="topbar"><span>Studio / <strong>Musikkbibliotek</strong></span><?php require dirname(__DIR__).'/app/views/account.php';?></header>
<main id="main" class="music-library-page"><div class="library-heading"><div><p class="eyebrow">RADIO RUBBEN / MUSIKK</p><h1>Musikkbibliotek</h1><p>Finn låten. Se opplysningene. Lytt før du velger.</p></div><div class="library-heading-actions"><a href="/ai-studio.php">Til Studio ↗</a><?php if($canUpload):?><a class="library-upload-link" href="#upload-drawer">Last opp musikk +</a><?php endif;?></div></div>
<?php if($error!==''):?><p class="notice" role="alert"><?=escape($error)?></p><?php endif;?>
<?php if($results):?><section class="library-result" aria-label="Resultat"><h2>Resultat av opplasting / klargjøring</h2><ul><?php foreach($results as$r):?><li><strong><?=escape($r['name'])?></strong> — <?=escape($r['message'])?></li><?php endforeach;?></ul></section><?php endif;?>
<details id="upload-drawer" class="library-panel library-upload" <?=!$tracks?'open':''?>><summary>Last opp musikk <span>Velg filer eller dra dem inn</span></summary><p>Prøvebibliotek: 100 filer / 512 MiB. Originaler lagres privat. Ingen automatisk avspilling.</p>
<?php if($canUpload&&$available):?><form method="post" enctype="multipart/form-data" id="music-upload-form"><input type="hidden" name="csrf" value="<?=escape($_SESSION['csrf'])?>"><input type="hidden" name="action" value="upload"><div id="music-drop-zone"><label for="music-files">Slipp MP3-filene her, eller velg filer<input id="music-files" name="tracks[]" type="file" accept=".mp3,audio/mpeg" multiple required></label></div><p id="music-file-status" role="status">Ingen filer valgt.</p><ul id="music-file-selection"></ul><p class="small">Inntil 10 filer, 20 MiB per fil og 64 MiB samlet. Identiske filer gjenbrukes.</p><p class="small">PHP-grenser: fil <?=escape((string)ini_get('upload_max_filesize'))?> · forespørsel <?=escape((string)ini_get('post_max_size'))?>.</p><button type="submit" class="button">Last opp originaler</button></form><?php elseif(!$canUpload):?><p>Administrator og produsent kan laste opp. Du kan lese biblioteket.</p><?php endif;?></details>
<div class="library-workspace"><section class="library-panel library-catalog" aria-labelledby="tracks-title"><div class="library-list-heading"><h2 id="tracks-title">Låter</h2><span><?=count($tracks)?> filer · <?=number_format(array_sum(array_column($tracks,'bytes'))/1048576,1,',',' ')?> MiB</span></div><div class="library-filters"><label>Søk i biblioteket<input type="search" id="library-search" placeholder="Artist, tittel, album eller filnavn"></label><label>Status<select id="library-filter"><option value="all">Alle låter</option><option value="pending">Venter på klargjøring</option><option value="prepared">Filopplysninger klar</option></select></label></div><p id="library-search-status" role="status" class="small"></p><div class="library-columns" aria-hidden="true"><span>Låt / artist</span><span>Album</span><span>Tid</span><span>Status</span></div>
<?php if($available&&!$tracks):?><p class="library-empty">Biblioteket er tomt. Start med prøvepakken din.</p><?php endif;?><ul class="library-tracks"><?php foreach($tracks as$t):$m=music_library_metadata($t);$fields=$m['fields']??[];?><li class="<?=$selected&&$selected['id']===$t['id']?'is-selected':''?>" data-library-state="<?=$m?'prepared':'pending'?>" data-library-search="<?=escape(implode(' ',[$t['originalName'],$fields['title']??'',$fields['artist']??'',$fields['album']??'']))?>"><div><a href="?track=<?=escape($t['id'])?>#track-detail"><?=escape($fields['title']??$t['originalName'])?></a><small><?=escape($fields['artist']??'Artist ikke lest')?></small></div><span class="library-album"><?=escape($fields['album']??'—')?></span><span class="library-duration"><?=music_library_duration($m)?></span><span class="library-state"><?=$t['available']?($m?'Fra filen':'Venter'):'Mangler original'?></span></li><?php endforeach;?></ul><noscript><p>Velg låten i listen. Søk og dra-og-slipp krever JavaScript; vanlig filvalg fungerer fortsatt.</p></noscript></section>
<aside id="track-detail" class="library-panel library-detail" aria-labelledby="track-detail-title"><?php if($selected):?><p class="eyebrow">VALGT LÅT</p><h2 id="track-detail-title"><?=escape($selectedMetadata['fields']['title']??$selected['originalName'])?></h2><p><?=escape($selectedMetadata['fields']['artist']??'Artist ikke lest')?></p><div class="library-detail-meta"><span><?=music_library_duration($selectedMetadata)?></span><span><?=number_format($selected['bytes']/1048576,1,',',' ')?> MiB</span></div><dl><?php foreach(['album'=>'Album','genre'=>'Sjanger fra filen','year'=>'År fra filen']as$k=>$label):?><div><dt><?=$label?></dt><dd><?=escape($selectedMetadata['fields'][$k]??'Ikke lest / mangler i filen')?></dd></div><?php endforeach;?></dl>
<p class="small">Opplysningene kommer fra originalfilen. Nettidentifisering, robotens merkelapper og programforslag kommer i neste trinn.</p>
<?php if($canUpload&&$selected['available']):?><form method="post"><input type="hidden" name="csrf" value="<?=escape($_SESSION['csrf'])?>"><input type="hidden" name="action" value="prepare"><input type="hidden" name="id" value="<?=escape($selected['id'])?>"><input type="hidden" name="version" value="<?=escape($selected['sha256'])?>"><input type="hidden" name="revision" value="<?=escape((string)($selected['revision']??0))?>"><button class="button" type="submit">Les filopplysninger og varighet</button></form><?php endif;?>
<?php if($canListen&&$selected['available']):?><section class="library-preview"><h3>Forhåndslytting</h3><p class="small">Kontroller lydutgangen. Dette er lokal lytting, ikke en kobling til sendingen.</p><label><input type="checkbox" id="preview-output-confirmed"> Lydutgangen er kontrollert for forhåndslytting</label><button type="button" id="library-preview-load" data-audio-url="/music-library-audio.php?id=<?=escape($selected['id'])?>&amp;version=<?=escape($selected['sha256'])?>" disabled>Forhåndslytt</button><audio id="library-preview-audio" controls preload="none" aria-label="Forhåndslytt valgt original"></audio><p id="library-preview-status" role="status" class="small">Ingen lyd er lastet.</p></section><?php endif;?>
<section class="library-cue-plan"><h3>Cue-punkter</h3><p class="small">Neste trinn: start, intro, overgang og slutt på en lydbølge. Ingen cue-punkter er lagret eller aktive ennå.</p></section><details><summary>Original og sporbarhet</summary><p class="small"><?=escape($selected['originalName'])?><br>ID <?=escape($selected['id'])?><br>Originalen beholdes urørt.</p></details>
<?php else:?><h2 id="track-detail-title">Velg en låt</h2><p>Opplysninger og forhåndslytting vises her.</p><?php endif;?></aside></div></main></div></div><script type="module" src="/assets/music-library.mjs?v=20261013-2"></script></body></html>
